('kill_boss', 0, 0, 0, 0, 0, 32, 0, 0, -1, -1, -1, 0, -1, 60, 0, -1, 0, 0, 0, 0, 3, '%target is dead. I wish that settled the debt. It does not.', 'career-veteran.txt line 83'),
